<div class="form-section mt-3"><h2 class="h5">Legacy organizational evidence</h2><?php if(!$legacyContexts): ?><p class="text-muted mb-0">No legacy organizational mapping was preserved.</p><?php else: ?><ul class="mb-0"><?php foreach($legacyContexts as $context): ?><li><?= e($context['legacy_level_key'].' - '.trim((string)$context['dad_number'].' '.(string)$context['name_en']).' (legacy '.$context['legacy_location_id'].')') ?></li><?php endforeach; ?></ul><?php endif; ?></div></div>
<div class="col-xl-7"><form class="form-section" method="post" action="<?= e(url('access-management/users/'.$identity['id'].'/activate')) ?>"><?= Csrf::field() ?><h2 class="h5">Current Access</h2><div class="alert alert-warning">The user, password, roles, and assigned locations will be activated together.</div>
<input type="hidden" name="identity_type" value="STAFF"><div class="row g-3"><div class="col-md-6"><label class="form-label">Username *</label><input class="form-control" name="username" value="<?= e($identity['username']) ?>" minlength="5" maxlength="50" required><div class="form-text">Enter the username this person will use to sign in.</div></div><div class="col-md-6"><label class="form-label">Email</label><input type="email" class="form-control" name="email"><div class="form-text">Enter the user's current email address.</div></div><div class="col-md-6"><label class="form-label">Temporary Password *</label><input type="password" class="form-control" name="temporary_password" minlength="8" required><div class="form-text">Use uppercase and lowercase letters, a number, and a symbol. The user must change this password after signing in.</div></div><div class="col-md-6"><label class="form-label">Start Date *</label><input type="date" class="form-control" name="effective_from" value="<?= e(date('Y-m-d')) ?>" required></div></div>
