<div class="mb-3"><label class="form-label">Reason *</label><textarea class="form-control" name="reason" rows="3" required></textarea></div><div class="mb-3"><label class="form-label">Reference</label><input class="form-control" name="official_reference"></div><button class="btn btn-primary">Activate User</button> <a class="btn btn-outline-secondary" href="<?= e(url('access-management/users/historical')) ?>">Cancel</a></form></div></div>
<script data-cfasync="false" nonce="<?= e(SecurityHeaders::nonce()) ?>">(()=>{const endpoint=<?= json_encode(url('access-management/assignment-locations'),JSON_THROW_ON_ERROR) ?>;for(const row of document.querySelectorAll('.access-role-row')){const check=row.querySelector('.access-role-check'),search=row.querySelector('.access-location-search'),select=row.querySelector('.access-location');if(!check)continue;let timer=0,request=null;const load=async()=>{if(!select||!check.checked)return;request?.abort();request=new AbortController();select.replaceChildren(new Option('Loading locations...',''));try{const query=new URLSearchParams({role_id:row.dataset.roleId,q:search?.value.trim()||'',limit:'100'}),response=await fetch(endpoint+'?'+query,{headers:{Accept:'application/json'},signal:request.signal});if(!response.ok)throw new Error('Location lookup denied');const data=await response.json();select.replaceChildren(new Option(data.results.length?'Select location':'No matching locations',''));for(const item of data.results)select.add(new Option([item.dad_number,item.name_en].filter(Boolean).join(' - '),item.id));}catch(error){if(error.name!=='AbortError')select.replaceChildren(new Option('Unable to load locations',''));}};check.addEventListener('change',()=>{if(select)select.disabled=!check.checked;if(search)search.disabled=!check.checked;if(check.checked)load();});search?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(load,250);});}document.querySelector('form')?.addEventListener('submit',function(){const enabled=new Set([...this.querySelectorAll('[name="role_enabled[]"]:checked')].map(x=>x.value));this.querySelectorAll('[name^="roles["]').forEach(field=>{if(!enabled.has(field.name.slice(6,-1)))field.disabled=true});});})();</script>
